BULLES_LOAD({"ep":"sophie/16","part":"text","paras":[{"poem":false,"s":[{"fr":"Sophie rentrait de la promenade avec son cousin Paul.","en":"Sophie was coming home from a walk with her cousin Paul.","pt":"A Sophie voltava do passeio com o primo Paul.","es":"Sophie volvía del paseo con su primo Paul."},{"fr":"Dans le vestibule attendait un homme qui semblait être un conducteur de diligence et qui tenait un paquet sous le bras.","en":"In the entrance hall a man was waiting who looked like a stagecoach driver and was holding a parcel under his arm.","pt":"No vestíbulo esperava um homem que parecia um cocheiro de diligência e que tinha um embrulho debaixo do braço.","es":"En el vestíbulo esperaba un hombre que parecía ser cochero de diligencia y que llevaba un paquete bajo el brazo."}]},{"poem":false,"s":[{"fr":"« Qui attendez-vous, monsieur ? » lui dit Paul très poliment.","en":"\"Who are you waiting for, sir?\" Paul asked him very politely.","pt":"— Está à espera de quem, senhor? — perguntou-lhe o Paul muito delicadamente.","es":"«¿A quién espera, señor?», le dijo Paul muy educadamente."}]},{"poem":false,"s":[{"fr":"J’attends Mme de Réan, monsieur ; j’ai un paquet à lui remettre.","en":"I'm waiting for Madame de Réan, sir; I have a parcel to give her.","pt":"Estou à espera da senhora de Réan, menino; tenho um embrulho para lhe entregar.","es":"Espero a la señora de Réan, señor; tengo que entregarle un paquete."}],"who":{"fr":"L’homme","en":"The man","pt":"O homem","es":"El hombre"}},{"poem":false,"s":[{"fr":"De la part de qui ?","en":"Who is it from?","pt":"Da parte de quem?","es":"¿De parte de quién?"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Je ne sais pas, mademoiselle, j’arrive de la diligence ; le paquet vient de Paris.","en":"I don't know, miss; I've just come from the stagecoach; the parcel comes from Paris.","pt":"Não sei, menina, venho da diligência; o embrulho vem de Paris.","es":"No lo sé, señorita; vengo de la diligencia; el paquete viene de París."}],"who":{"fr":"L’homme","en":"The man","pt":"O homem","es":"El hombre"}},{"poem":false,"s":[{"fr":"Mais qu’est-ce qu’il y a dans le paquet ?","en":"But what's in the parcel?","pt":"Mas o que é que tem o embrulho?","es":"Pero ¿qué hay en el paquete?"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Je pense que ce sont des fruits confits et des pâtes d’abricots.","en":"I think it's candied fruit and apricot jellies.","pt":"Acho que são frutas cristalizadas e pastas de alperce.","es":"Creo que es fruta confitada y pasta de albaricoque."},{"fr":"Du moins c’est comme cela qu’ils sont inscrits sur le livre de la diligence. »","en":"At least that's how they're entered in the stagecoach book.\"","pt":"Pelo menos é assim que estão inscritas no livro da diligência.","es":"Por lo menos, así está apuntado en el libro de la diligencia»."}],"who":{"fr":"L’homme","en":"The man","pt":"O homem","es":"El hombre"}},{"poem":false,"s":[{"fr":"Les yeux de Sophie brillèrent ; elle passa sa langue sur ses lèvres.","en":"Sophie's eyes shone; she ran her tongue over her lips.","pt":"Os olhos da Sophie brilharam; passou a língua pelos lábios.","es":"A Sophie le brillaron los ojos; se pasó la lengua por los labios."}]},{"poem":false,"s":[{"fr":"« Allons vite prévenir maman », dit-elle à Paul ; et elle partit en courant.","en":"\"Let's hurry and tell Mama,\" she said to Paul, and she ran off.","pt":"— Vamos depressa avisar a mamã — disse ela ao Paul; e partiu a correr.","es":"«Vamos deprisa a avisar a mamá», le dijo a Paul; y se fue corriendo."},{"fr":"Quelques instants après, la maman arriva, paya le port du paquet et l’emporta au salon, où la suivirent Sophie et Paul.","en":"A few moments later her mother arrived, paid the carriage on the parcel and took it to the drawing room, where Sophie and Paul followed her.","pt":"Uns instantes depois, a mãe chegou, pagou o porte do embrulho e levou-o para a sala, para onde a seguiram a Sophie e o Paul.","es":"Unos instantes después llegó su mamá, pagó el porte del paquete y se lo llevó al salón, adonde la siguieron Sophie y Paul."},{"fr":"Ils furent très attrapés quand ils virent Mme de Réan poser le paquet sur la table et retourner à son bureau pour lire et écrire.","en":"They were very disappointed when they saw Madame de Réan put the parcel on the table and go back to her desk to read and write.","pt":"Ficaram muito desapontados quando viram a senhora de Réan pousar o embrulho na mesa e voltar para a secretária para ler e escrever.","es":"Se llevaron un buen chasco cuando vieron a la señora de Réan dejar el paquete en la mesa y volver a su escritorio para leer y escribir."}]},{"poem":false,"s":[{"fr":"Sophie et Paul se regardèrent d’un air malheureux.","en":"Sophie and Paul looked at each other miserably.","pt":"A Sophie e o Paul olharam um para o outro com ar infeliz.","es":"Sophie y Paul se miraron con aire desgraciado."}]},{"poem":false,"s":[{"fr":"« Demande à maman de l’ouvrir, dit tout bas Sophie à Paul.","en":"\"Ask Mama to open it,\" Sophie whispered to Paul.","pt":"— Pede à mamã para o abrir — disse a Sophie muito baixinho ao Paul.","es":"«Pídele a mamá que lo abra», le dijo Sophie a Paul en voz muy baja."}]},{"poem":false,"s":[{"fr":"Je n’ose pas ; ma tante n’aime pas qu’on soit impatient et curieux.","en":"I don't dare; my aunt doesn't like people being impatient and nosy.","pt":"Não me atrevo; a tia não gosta que sejamos impacientes e curiosos.","es":"No me atrevo; a mi tía no le gusta que uno sea impaciente y curioso."}],"who":{"fr":"Paul, tout bas","en":"Paul, in a whisper","pt":"Paul, muito baixinho","es":"Paul, en voz muy baja"}},{"poem":false,"s":[{"fr":"Demande-lui si elle veut que nous lui épargnions la peine d’ouvrir le paquet en l’ouvrant nous-mêmes.","en":"Ask her if she'd like us to save her the trouble of opening the parcel by opening it ourselves.","pt":"Pergunta-lhe se quer que lhe poupemos o trabalho de abrir o embrulho, abrindo-o nós.","es":"Pregúntale si quiere que le ahorremos el trabajo de abrir el paquete abriéndolo nosotros."}],"who":{"fr":"Sophie, tout bas","en":"Sophie, in a whisper","pt":"Sophie, muito baixinho","es":"Sophie, en voz muy baja"}},{"poem":false,"s":[{"fr":"J’entends très bien ce que vous dites, Sophie ; c’est très mal de faire la fausse, de faire semblant d’être obligeante et de vouloir m’épargner un ennui, quand c’est tout bonnement par curiosité et par gourmandise que tu veux ouvrir ce paquet.","en":"I can hear perfectly well what you're saying, Sophie; it's very wrong to be sly, to pretend to be helpful and want to spare me a chore, when it's simply out of curiosity and greed that you want to open this parcel.","pt":"Ouço muito bem o que estão a dizer, Sophie; é muito feio ser fingida, fazer de conta que se é prestável e que se me quer poupar uma maçada, quando é simplesmente por curiosidade e gulodice que queres abrir este embrulho.","es":"Oigo muy bien lo que decís, Sophie; está muy mal hacerse la falsa, fingir que eres servicial y que quieres ahorrarme una molestia, cuando lo que quieres es abrir ese paquete por pura curiosidad y glotonería."}],"who":{"fr":"La maman","en":"Mother","pt":"a mãe","es":"Mamá"}},{"poem":false,"s":[{"fr":"Si tu m’avais dit franchement : « Maman, j’ai envie de voir les fruits confits, permettez-moi de défaire le paquet », je te l’aurais permis.","en":"If you had said to me frankly, 'Mama, I'd love to see the candied fruit; let me undo the parcel,' I would have let you.","pt":"Se me tivesses dito francamente: «Mamã, tenho vontade de ver as frutas cristalizadas, deixe-me desfazer o embrulho», eu tinha deixado.","es":"Si me hubieras dicho con franqueza: «Mamá, tengo ganas de ver la fruta confitada; déjeme abrir el paquete», te lo habría permitido."},{"fr":"Maintenant je te défends d’y toucher. »","en":"Now I forbid you to touch it.\"","pt":"Agora proíbo-te de lhe tocar.","es":"Ahora te prohíbo tocarlo»."}]},{"poem":false,"s":[{"fr":"Sophie, confuse et mécontente, s’en alla dans sa chambre, suivie de Paul.","en":"Sophie, embarrassed and cross, went off to her room, followed by Paul.","pt":"A Sophie, envergonhada e descontente, foi para o quarto, seguida do Paul.","es":"Sophie, avergonzada y descontenta, se fue a su cuarto, seguida de Paul."}]},{"poem":false,"s":[{"fr":"« Voilà ce que c’est que d’avoir voulu faire des finesses, lui dit Paul.","en":"\"That's what comes of trying to be clever,\" Paul said to her.","pt":"— É no que dá quereres armar-te em esperta — disse-lhe o Paul.","es":"«Esto es lo que pasa por querer hacerse la lista», le dijo Paul."},{"fr":"Tu fais toujours comme cela, et tu sais que ma tante déteste les faussetés.","en":"\"You always do that, and you know my aunt hates sly tricks.","pt":"— Fazes sempre assim, e sabes que a tia detesta fingimentos.","es":"«Siempre haces lo mismo, y sabes que mi tía detesta las falsedades."}]},{"poem":false,"s":[{"fr":"Pourquoi aussi n’as-tu pas demandé tout de suite quand je te l’ai dit ?","en":"Well, why didn't you ask straight away when I told you to?","pt":"Então porque é que não pediste logo quando eu te disse?","es":"¿Y por qué no se lo pediste enseguida cuando te lo dije?"},{"fr":"Tu veux toujours faire le sage et tu ne fais que des bêtises.","en":"You always try to act the good boy, and all you do is silly things.","pt":"Estás sempre a armar-te em ajuizado e só fazes asneiras.","es":"Siempre quieres hacerte el formal y no haces más que tonterías."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"D’abord je ne fais pas de bêtises ; ensuite je ne fais pas le sage.","en":"First of all, I don't do silly things; and secondly, I don't act the good boy.","pt":"Primeiro, eu não faço asneiras; segundo, não me armo em ajuizado.","es":"Para empezar, yo no hago tonterías; y además no me hago el formal."},{"fr":"Tu dis cela parce que tu es furieuse de ne pas avoir les fruits confits.","en":"You're saying that because you're furious not to have the candied fruit.","pt":"Dizes isso porque estás furiosa por não teres as frutas cristalizadas.","es":"Dices eso porque estás furiosa por no tener la fruta confitada."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Pas du tout, monsieur, je ne suis furieuse que contre vous, parce que vous me faites toujours gronder.","en":"Not at all, sir; I'm only furious with you, because you always get me told off.","pt":"Nada disso, senhor, só estou furiosa consigo, porque está sempre a fazer com que ralhem comigo.","es":"Nada de eso, señor; solo estoy furiosa con usted, porque siempre hace que me regañen."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Même le jour où tu m’as si bien griffé ? »","en":"Even the day you scratched me so badly?\"","pt":"Até no dia em que me arranhaste tão bem?","es":"¿Incluso el día que me arañaste tan bien?»."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Sophie, honteuse, rougit et se tut.","en":"Sophie, ashamed, went red and said nothing.","pt":"A Sophie, envergonhada, corou e calou-se.","es":"Sophie, avergonzada, se sonrojó y se calló."},{"fr":"Ils restèrent quelque temps sans se parler ; Sophie aurait bien voulu demander pardon à Paul, mais l’amour-propre l’empêchait de parler la première.","en":"For a while they didn't speak to each other; Sophie would have liked to say sorry to Paul, but her pride stopped her speaking first.","pt":"Ficaram algum tempo sem falar um com o outro; a Sophie bem queria pedir desculpa ao Paul, mas o amor-próprio impedia-a de falar primeiro.","es":"Se quedaron un rato sin hablarse; a Sophie le habría gustado pedirle perdón a Paul, pero el amor propio le impedía hablar la primera."},{"fr":"Paul, qui était très bon, n’en voulait plus à Sophie ; mais il ne savait comment faire pour commencer la conversation.","en":"Paul, who was very kind, was no longer cross with Sophie; but he didn't know how to start the conversation.","pt":"O Paul, que era muito bom, já não estava zangado com a Sophie; mas não sabia como começar a conversa.","es":"Paul, que era muy bueno, ya no le guardaba rencor a Sophie; pero no sabía cómo empezar la conversación."},{"fr":"Enfin, il trouva un moyen très habile : il se balança sur sa chaise, et il se pencha tellement en arrière, qu’il tomba.","en":"At last he found a very clever way: he rocked on his chair and leaned back so far that he fell over.","pt":"Por fim, encontrou uma maneira muito hábil: baloiçou-se na cadeira e inclinou-se tanto para trás que caiu.","es":"Por fin encontró un medio muy hábil: se balanceó en la silla y se echó tanto hacia atrás que se cayó."},{"fr":"Sophie accourut pour l’aider à se relever.","en":"Sophie ran over to help him up.","pt":"A Sophie acorreu para o ajudar a levantar-se.","es":"Sophie acudió corriendo a ayudarle a levantarse."}]},{"poem":false,"s":[{"fr":"« Tu t’es fait mal, pauvre Paul ? lui dit-elle.","en":"\"Have you hurt yourself, poor Paul?\" she said.","pt":"— Magoaste-te, pobre Paul? — disse-lhe ela.","es":"«¿Te has hecho daño, pobre Paul?», le dijo."}]},{"poem":false,"s":[{"fr":"Non, au contraire.","en":"No, quite the opposite.","pt":"Não, pelo contrário.","es":"No, al contrario."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Ah ! au contraire.","en":"Oh! The opposite.","pt":"Ah! Pelo contrário.","es":"¡Ah! Al contrario."},{"fr":"C’est assez drôle, cela.","en":"That's rather funny.","pt":"Essa é engraçada.","es":"Pues sí que es gracioso."}],"who":{"fr":"Sophie, riant","en":"Sophie, laughing","pt":"Sophie, a rir","es":"Sophie, riendo"}},{"poem":false,"s":[{"fr":"Oui ! puisqu’en tombant j’ai fait finir notre querelle.","en":"Yes! Because by falling over I've ended our quarrel.","pt":"Pois! Porque, ao cair, acabei com a nossa zanga.","es":"¡Sí! Porque, al caerme, he hecho que se acabe nuestra pelea."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Mon bon Paul, comme tu es bon !","en":"My good Paul, how kind you are!","pt":"Meu bom Paul, como és bom!","es":"¡Mi buen Paul, qué bueno eres!"},{"fr":"C’est donc exprès que tu es tombé ? tu aurais pu te faire mal.","en":"So you fell over on purpose? You could have hurt yourself.","pt":"Então caíste de propósito? Podias ter-te magoado.","es":"¿Así que te has caído a propósito? Podrías haberte hecho daño."}],"who":{"fr":"Sophie, l’embrassant","en":"Sophie, kissing her","pt":"Sophie, beijando-a","es":"Sophie, besándola"}},{"poem":false,"s":[{"fr":"Non ; comment veux-tu qu’on se fasse mal en tombant d’une chaise si basse ?","en":"No; how could anyone hurt themselves falling off such a low chair?","pt":"Não; como queres que alguém se magoe a cair de uma cadeira tão baixa?","es":"No; ¿cómo quieres que uno se haga daño cayéndose de una silla tan baja?"},{"fr":"À présent que nous sommes amis, allons jouer. »","en":"Now that we're friends, let's go and play.\"","pt":"Agora que somos amigos, vamos brincar.","es":"Ahora que somos amigos, vamos a jugar»."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Et ils partirent en courant.","en":"And they ran off.","pt":"E partiram a correr.","es":"Y se fueron corriendo."},{"fr":"En traversant le salon, ils virent le paquet toujours ficelé.","en":"Crossing the drawing room, they saw the parcel, still tied up.","pt":"Ao atravessar a sala, viram o embrulho ainda atado.","es":"Al cruzar el salón, vieron el paquete todavía atado."},{"fr":"Paul entraîna Sophie, qui avait bien envie de s’arrêter, et ils n’y pensèrent plus.","en":"Paul dragged Sophie along, though she very much wanted to stop, and they didn't think about it any more.","pt":"O Paul arrastou a Sophie, que tinha muita vontade de parar, e não pensaram mais naquilo.","es":"Paul arrastró a Sophie, que tenía muchas ganas de pararse, y ya no pensaron más en él."}]},{"poem":false,"s":[{"fr":"Après le dîner, Mme de Réan appela les enfants.","en":"After dinner Madame de Réan called the children.","pt":"Depois do jantar, a senhora de Réan chamou as crianças.","es":"Después de la cena, la señora de Réan llamó a los niños."}]},{"poem":false,"s":[{"fr":"« Nous allons enfin ouvrir le fameux paquet, dit-elle, et goûter à nos fruits confits.","en":"\"At last we're going to open the famous parcel,\" she said, \"and taste our candied fruit.","pt":"— Vamos finalmente abrir o famoso embrulho — disse ela — e provar as nossas frutas cristalizadas.","es":"«Por fin vamos a abrir el famoso paquete», dijo, «y a probar nuestra fruta confitada."},{"fr":"Paul, va me chercher un couteau pour couper la ficelle. »","en":"Paul, go and fetch me a knife to cut the string.\"","pt":"Paul, vai buscar-me uma faca para cortar o cordel.","es":"Paul, ve a buscarme un cuchillo para cortar la cuerda»."},{"fr":"Paul partit comme un éclair et rentra presque au même instant, tenant un couteau, qu’il présenta à sa tante.","en":"Paul shot off like lightning and came back almost at once with a knife, which he handed to his aunt.","pt":"O Paul partiu como um relâmpago e voltou quase no mesmo instante com uma faca, que entregou à tia.","es":"Paul salió como un rayo y volvió casi en el mismo instante con un cuchillo, que le dio a su tía."}]},{"poem":false,"s":[{"fr":"Mme de Réan coupa la ficelle, défit les papiers qui enveloppaient les fruits, et découvrit douze boîtes de fruits confits et de pâtes d’abricots.","en":"Madame de Réan cut the string, undid the paper wrapped round the fruit and uncovered twelve boxes of candied fruit and apricot jellies.","pt":"A senhora de Réan cortou o cordel, desfez os papéis que embrulhavam as frutas e descobriu doze caixas de frutas cristalizadas e de pastas de alperce.","es":"La señora de Réan cortó la cuerda, quitó los papeles que envolvían la fruta y descubrió doce cajas de fruta confitada y de pasta de albaricoque."}]},{"poem":false,"s":[{"fr":"« Goûtons-les pour voir s’ils sont bons, dit-elle en ouvrant une boîte.","en":"\"Let's taste them to see if they're good,\" she said, opening a box.","pt":"— Vamos prová-las para ver se são boas — disse ela, abrindo uma caixa.","es":"«Vamos a probarlas para ver si están buenas», dijo abriendo una caja."},{"fr":"Prends-en deux, Sophie ; choisis ceux que tu aimeras le mieux.","en":"\"Take two, Sophie; choose the ones you like best.","pt":"— Tira duas, Sophie; escolhe as de que mais gostares.","es":"«Coge dos, Sophie; elige las que más te gusten."},{"fr":"Voici des poires, des prunes, des noix, des abricots, du cédrat, de l’angélique. »","en":"There are pears, plums, walnuts, apricots, citron and angelica.\"","pt":"Aqui há pêras, ameixas, nozes, alperces, cidrão e angélica.","es":"Aquí hay peras, ciruelas, nueces, albaricoques, cidra y angélica»."}]},{"poem":false,"s":[{"fr":"Sophie hésita un peu ; elle examinait lesquels étaient les plus gros ; enfin elle se décida pour une poire et un abricot.","en":"Sophie hesitated a little; she was looking to see which were the biggest; at last she decided on a pear and an apricot.","pt":"A Sophie hesitou um pouco; examinava quais eram as maiores; por fim decidiu-se por uma pêra e um alperce.","es":"Sophie dudó un poco; miraba cuáles eran las más grandes; por fin se decidió por una pera y un albaricoque."},{"fr":"Paul choisit une prune et de l’angélique.","en":"Paul chose a plum and some angelica.","pt":"O Paul escolheu uma ameixa e angélica.","es":"Paul eligió una ciruela y angélica."},{"fr":"Quand tout le monde en eut pris, la maman ferma la boîte, encore à moitié pleine, la porta dans sa chambre et la posa sur le haut d’une étagère.","en":"When everyone had had some, her mother shut the box, still half full, took it to her room and put it on top of a high shelf.","pt":"Quando todos se tinham servido, a mãe fechou a caixa, ainda meio cheia, levou-a para o quarto e pô-la no alto de uma prateleira.","es":"Cuando todos hubieron cogido, la mamá cerró la caja, todavía medio llena, la llevó a su cuarto y la puso en lo alto de una estantería."},{"fr":"Sophie l’avait suivie jusqu’à la porte.","en":"Sophie had followed her as far as the door.","pt":"A Sophie tinha-a seguido até à porta.","es":"Sophie la había seguido hasta la puerta."}]},{"poem":false,"s":[{"fr":"En revenant, Mme de Réan dit à Sophie et à Paul qu’elle ne pourrait les mener promener, parce qu’elle devait faire une visite dans le voisinage.","en":"When she came back, Madame de Réan told Sophie and Paul that she couldn't take them for a walk, because she had to pay a visit in the neighbourhood.","pt":"Ao voltar, a senhora de Réan disse à Sophie e ao Paul que não os podia levar a passear, porque tinha de fazer uma visita na vizinhança.","es":"Al volver, la señora de Réan les dijo a Sophie y a Paul que no podría llevarlos de paseo, porque tenía que hacer una visita por los alrededores."}]},{"poem":false,"s":[{"fr":"« Amusez-vous pendant mon absence, mes enfants ; promenez-vous, ou restez devant la maison, comme vous voudrez. »","en":"\"Have fun while I'm away, children; go for a walk or stay in front of the house, whichever you like.\"","pt":"— Divirtam-se enquanto eu estiver fora, meninos; vão passear ou fiquem à frente de casa, como quiserem.","es":"«Divertíos mientras estoy fuera, niños; dad un paseo o quedaos delante de la casa, como queráis»."}]},{"poem":false,"s":[{"fr":"Et, les embrassant, elle monta en voiture avec M. et Mme d’Aubert et M. de Réan.","en":"And kissing them, she got into the carriage with Monsieur and Madame d'Aubert and Monsieur de Réan.","pt":"E, dando-lhes um beijo, subiu para a carruagem com o senhor e a senhora d'Aubert e o senhor de Réan.","es":"Y, después de besarlos, subió al coche con el señor y la señora d'Aubert y el señor de Réan."}]},{"poem":false,"s":[{"fr":"Les enfants restèrent seuls et jouèrent longtemps devant la maison.","en":"The children were left alone and played for a long time in front of the house.","pt":"As crianças ficaram sozinhas e brincaram muito tempo à frente de casa.","es":"Los niños se quedaron solos y jugaron mucho rato delante de la casa."},{"fr":"Sophie parlait souvent de fruits confits.","en":"Sophie kept talking about candied fruit.","pt":"A Sophie falava muitas vezes das frutas cristalizadas.","es":"Sophie hablaba a menudo de la fruta confitada."}]},{"poem":false,"s":[{"fr":"« Je suis fâchée, dit-elle, de n’avoir pas pris d’angélique ni de prune ; ce doit être très bon.","en":"\"I'm sorry,\" she said, \"that I didn't take any angelica or plum; they must be very good.\"","pt":"— Tenho pena — disse ela — de não ter tirado angélica nem ameixa; deve ser muito bom.","es":"«Siento no haber cogido angélica ni ciruela», dijo; «deben de estar muy buenas."}]},{"poem":false,"s":[{"fr":"— Oui, c’est très bon, répondit Paul, mais tu pourras en manger demain ; ainsi n’y pense plus, crois-moi, et jouons. »","en":"\"Yes, they're very good,\" answered Paul, \"but you'll be able to have some tomorrow; so stop thinking about it, believe me, and let's play.\"","pt":"— Sim, é muito bom — respondeu o Paul —, mas amanhã podes comer; por isso não penses mais nisso, acredita, e vamos brincar.","es":"—Sí, están muy buenas», respondió Paul, «pero podrás comer mañana; así que no pienses más en ello, hazme caso, y juguemos»."}]},{"poem":false,"s":[{"fr":"Ils reprirent leur jeu, qui était de l’invention de Paul.","en":"They went back to their game, which Paul had invented.","pt":"Voltaram à brincadeira, que tinha sido inventada pelo Paul.","es":"Volvieron a su juego, que era un invento de Paul."},{"fr":"Ils avaient creusé un petit bassin et ils le remplissaient d’eau ; mais il fallait en remettre toujours, parce que la terre buvait l’eau à mesure qu’ils la versaient.","en":"They had dug a little pond and were filling it with water; but they had to keep adding more, because the earth drank up the water as fast as they poured it in.","pt":"Tinham cavado um pequeno lago e enchiam-no de água; mas era sempre preciso pôr mais, porque a terra bebia a água à medida que a deitavam.","es":"Habían cavado un pequeño estanque y lo llenaban de agua; pero había que echar más todo el rato, porque la tierra se bebía el agua a medida que la echaban."},{"fr":"Enfin, Paul glissa sur la terre boueuse et renversa un arrosoir plein sur ses jambes.","en":"In the end Paul slipped on the muddy earth and tipped a full watering can over his legs.","pt":"Por fim, o Paul escorregou na terra lamacenta e entornou um regador cheio nas pernas.","es":"Por fin, Paul resbaló en la tierra embarrada y se volcó una regadera llena encima de las piernas."}]},{"poem":false,"s":[{"fr":"« Aïe, aïe ! s’écria-t-il, comme c’est froid !","en":"\"Ow, ow!\" he cried. \"How cold it is!","pt":"— Ai, ai! — exclamou ele. — Que frio!","es":"«¡Ay, ay!», exclamó, «¡qué fría está!"},{"fr":"Je suis trempé ; il faut que j’aille changer de souliers, de bas, de pantalon.","en":"I'm soaked; I have to go and change my shoes, my socks and my trousers.","pt":"Estou encharcado; tenho de ir mudar de sapatos, de meias e de calças.","es":"Estoy empapado; tengo que ir a cambiarme de zapatos, de medias y de pantalón."},{"fr":"Attends-moi là, je reviendrai dans un quart d’heure. »","en":"Wait for me here; I'll be back in a quarter of an hour.\"","pt":"Espera aqui por mim, volto daqui a um quarto de hora.","es":"Espérame aquí; vuelvo dentro de un cuarto de hora»."}]},{"poem":false,"s":[{"fr":"Sophie resta près du bassin, tapotant l’eau avec sa petite pelle, mais ne pensant ni à l’eau, ni à la pelle, ni à Paul.","en":"Sophie stayed by the pond, patting the water with her little spade, but thinking neither of the water, nor the spade, nor Paul.","pt":"A Sophie ficou ao pé do lago, a bater na água com a pazinha, mas sem pensar nem na água, nem na pá, nem no Paul.","es":"Sophie se quedó junto al estanque, golpeando el agua con su palita, pero sin pensar ni en el agua, ni en la pala, ni en Paul."},{"fr":"À quoi pensait-elle donc ?","en":"So what was she thinking about?","pt":"Em que pensava ela, então?","es":"¿En qué pensaba entonces?"},{"fr":"Hélas !","en":"Alas!","pt":"Ai!","es":"¡Ay!"},{"fr":"Sophie pensait aux fruits confits, à l’angélique, aux prunes ; elle regrettait de ne pas pouvoir en manger encore, de n’avoir pas goûté à tout.","en":"Sophie was thinking about candied fruit, angelica and plums; she was sorry she couldn't eat any more and that she hadn't tasted them all.","pt":"A Sophie pensava nas frutas cristalizadas, na angélica, nas ameixas; tinha pena de não poder comer mais, de não ter provado tudo.","es":"Sophie pensaba en la fruta confitada, en la angélica, en las ciruelas; sentía no poder comer más, no haberlo probado todo."}]},{"poem":false,"s":[{"fr":"« Demain, pensa-t-elle, maman m’en donnera encore ; je n’aurai pas le temps de bien choisir.","en":"\"Tomorrow,\" she thought, \"Mama will give me some more; I won't have time to choose properly.","pt":"— Amanhã — pensou ela —, a mamã dá-me mais; não vou ter tempo de escolher bem.","es":"«Mañana», pensó, «mamá me dará más; no tendré tiempo de elegir bien."},{"fr":"Si je pouvais les regarder d’avance, je remarquerais ceux que je prendrai demain…","en":"If I could look at them beforehand, I'd notice which ones I'll take tomorrow…","pt":"Se eu as pudesse ver antes, ficava a saber quais vou tirar amanhã…","es":"Si pudiera mirarlas antes, me fijaría en las que voy a coger mañana…"},{"fr":"Et pourquoi ne pourrais-je pas les regarder ?","en":"And why shouldn't I look at them?","pt":"E porque é que não as hei de ver?","es":"¿Y por qué no voy a poder mirarlas?"},{"fr":"Je n’ai qu’à ouvrir la boîte. »","en":"I only have to open the box.\"","pt":"Basta abrir a caixa.","es":"No tengo más que abrir la caja»."}]},{"poem":false,"s":[{"fr":"Voilà Sophie, bien contente de son idée, qui court à la chambre de sa maman et qui cherche à atteindre la boîte ;","en":"And off goes Sophie, very pleased with her idea, running to her mother's room and trying to reach the box;","pt":"E lá vai a Sophie, muito contente com a sua ideia, a correr para o quarto da mãe à procura de chegar à caixa;","es":"Y ahí va Sophie, muy contenta con su idea, que corre al cuarto de su mamá e intenta alcanzar la caja;"},{"fr":"mais elle a beau sauter, allonger le bras, elle ne peut y parvenir ;","en":"but however much she jumps and stretches out her arm, she can't reach it;","pt":"mas, por mais que salte e estique o braço, não consegue lá chegar;","es":"pero por mucho que salta y estira el brazo, no llega;"},{"fr":"elle ne sait comment faire ; elle cherche un bâton, une pincette, n’importe quoi, lorsqu’elle se tape le front avec la main en disant :","en":"she doesn't know what to do; she looks for a stick, a pair of tongs, anything, when she slaps her forehead and says:","pt":"não sabe como fazer; procura um pau, uma tenaz, qualquer coisa, quando dá uma palmada na testa, dizendo:","es":"no sabe cómo hacerlo; busca un palo, unas tenazas, lo que sea, cuando se da una palmada en la frente diciendo:"}]},{"poem":false,"s":[{"fr":"« Que je suis donc bête ! je vais approcher un fauteuil et monter dessus ! »","en":"\"How silly I am! I'll pull up an armchair and climb on it!\"","pt":"— Que tonta que eu sou! Vou chegar uma poltrona e subir para cima dela!","es":"«¡Qué tonta soy! ¡Voy a acercar un sillón y a subirme encima!»."}]},{"poem":false,"s":[{"fr":"Sophie tire et pousse un lourd fauteuil tout près de l’étagère, grimpe dessus, atteint la boîte, l’ouvre et regarde avec envie les beaux fruits confits.","en":"Sophie pulls and pushes a heavy armchair right up to the shelf, climbs onto it, reaches the box, opens it and gazes longingly at the beautiful candied fruit.","pt":"A Sophie puxa e empurra uma poltrona pesada até ao pé da prateleira, trepa para cima dela, chega à caixa, abre-a e olha com cobiça para as belas frutas cristalizadas.","es":"Sophie tira y empuja un sillón pesado hasta muy cerca de la estantería, se sube encima, alcanza la caja, la abre y mira con envidia la preciosa fruta confitada."},{"fr":"« Lequel prendrai-je demain ? » dit-elle.","en":"\"Which one shall I take tomorrow?\" she said.","pt":"— Qual vou tirar amanhã? — disse ela.","es":"«¿Cuál cogeré mañana?», dice."},{"fr":"Elle ne peut se décider : c’est tantôt l’un, tantôt l’autre.","en":"She can't make up her mind: first it's one, then another.","pt":"Não se consegue decidir: ora é uma, ora é outra.","es":"No consigue decidirse: unas veces es una y otras veces otra."},{"fr":"Le temps se passait pourtant ; Paul allait bientôt revenir.","en":"Meanwhile time was passing; Paul would soon be back.","pt":"Entretanto, o tempo passava; o Paul ia voltar daí a pouco.","es":"Sin embargo, el tiempo pasaba; Paul iba a volver pronto."}]},{"poem":false,"s":[{"fr":"« Que dirait-il s’il me voyait ici ? pensa-t-elle.","en":"\"What would he say if he saw me here?\" she thought.","pt":"— Que diria ele se me visse aqui? — pensou ela.","es":"«¿Qué diría si me viera aquí?», pensó."},{"fr":"Il croirait que je vole les fruits confits, et pourtant je ne fais que les regarder…","en":"\"He'd think I was stealing the candied fruit, and yet I'm only looking at it…","pt":"— Pensava que eu estava a roubar as frutas cristalizadas, e afinal só estou a olhar para elas…","es":"«Creería que estoy robando la fruta confitada, y sin embargo solo la estoy mirando…"},{"fr":"J’ai une bonne idée : si je grignotais un tout petit morceau de chaque fruit, je saurais le goût qu’ils ont tous, je saurais lequel est le meilleur, et personne ne verrait rien, parce que j’en mordrais si peu que cela ne paraîtrait pas. »","en":"I've got a good idea: if I nibbled a tiny bit of each fruit, I'd know what they all taste like, I'd know which is the best, and nobody would see anything, because I'd bite off so little it wouldn't show.\"","pt":"Tenho uma boa ideia: se eu roesse um bocadinho de cada fruta, ficava a saber o sabor de todas, sabia qual era a melhor, e ninguém via nada, porque mordia tão pouco que não se notava.","es":"Tengo una buena idea: si mordisqueara un trocito muy pequeño de cada fruta, sabría a qué saben todas, sabría cuál es la mejor, y nadie vería nada, porque mordería tan poco que no se notaría»."}]},{"poem":false,"s":[{"fr":"Et Sophie mordille un morceau d’angélique, puis un abricot, puis une prune, puis une noix, puis une poire, puis du cédrat, mais elle ne se décide pas plus qu’avant.","en":"And Sophie nibbles a piece of angelica, then an apricot, then a plum, then a walnut, then a pear, then some citron, but she can't decide any better than before.","pt":"E a Sophie trinca um bocado de angélica, depois um alperce, depois uma ameixa, depois uma noz, depois uma pêra, depois cidrão, mas não se decide mais do que antes.","es":"Y Sophie mordisquea un trozo de angélica, luego un albaricoque, luego una ciruela, luego una nuez, luego una pera, luego cidra, pero sigue sin decidirse."}]},{"poem":false,"s":[{"fr":"« Il faut recommencer », dit-elle.","en":"\"I'll have to start again,\" she said.","pt":"— Tenho de recomeçar — disse ela.","es":"«Hay que volver a empezar», dice."}]},{"poem":false,"s":[{"fr":"Elle recommence à grignoter, et recommence tant de fois, qu’il ne reste presque plus rien dans la boîte.","en":"She starts nibbling again, and starts again so many times that there's hardly anything left in the box.","pt":"Recomeça a roer, e recomeça tantas vezes que já quase não fica nada na caixa.","es":"Vuelve a mordisquear, y vuelve a empezar tantas veces que casi no queda nada en la caja."},{"fr":"Elle s’en aperçoit enfin ; la frayeur la prend.","en":"At last she notices; she's seized with fright.","pt":"Por fim dá por isso; fica cheia de medo.","es":"Por fin se da cuenta; le entra miedo."}]},{"poem":false,"s":[{"fr":"« Mon Dieu, mon Dieu ! qu’ai-je fait ? dit-elle.","en":"\"Oh dear, oh dear! What have I done?\" she said.","pt":"— Meu Deus, meu Deus! Que fiz eu? — disse ela.","es":"«¡Dios mío, Dios mío! ¿Qué he hecho?», dice."},{"fr":"Je ne voulais qu’y goûter, et j’ai presque tout mangé.","en":"\"I only wanted to taste them, and I've eaten nearly everything.","pt":"— Só queria provar, e comi quase tudo.","es":"«Solo quería probarlas, y me las he comido casi todas."}]},{"poem":false,"s":[{"fr":"Maman va s’en apercevoir dès qu’elle ouvrira la boîte ; elle devinera que c’est moi.","en":"Mama will notice as soon as she opens the box; she'll guess it was me.","pt":"A mamã vai dar por isso assim que abrir a caixa; vai adivinhar que fui eu.","es":"Mamá se dará cuenta en cuanto abra la caja; adivinará que he sido yo."},{"fr":"Que faire, que faire ?…","en":"What shall I do, what shall I do?…","pt":"Que hei de fazer, que hei de fazer?…","es":"¿Qué hago, qué hago?…"},{"fr":"Je pourrais bien dire que ce n’est pas moi ; mais maman ne me croira pas…","en":"I could say it wasn't me; but Mama won't believe me…","pt":"Podia dizer que não fui eu; mas a mamã não vai acreditar…","es":"Podría decir que no he sido yo; pero mamá no me creerá…"},{"fr":"Si je disais que ce sont les souris ?","en":"What if I said it was the mice?","pt":"E se eu dissesse que foram os ratos?","es":"¿Y si dijera que han sido los ratones?"},{"fr":"Précisément, j’en ai vu une courir ce matin dans le corridor.","en":"Exactly; I saw one running along the corridor this morning.","pt":"Isso mesmo, vi um a correr esta manhã no corredor.","es":"Precisamente esta mañana he visto uno correr por el pasillo."},{"fr":"Je le dirai à maman ; seulement je dirai que c’était un rat, parce qu’un rat est plus gros qu’une souris, et qu’il mange plus, et, comme j’ai mangé presque tout, il vaut mieux que ce soit un rat qu’une souris. »","en":"I'll tell Mama; only I'll say it was a rat, because a rat is bigger than a mouse and eats more, and since I've eaten nearly everything, it's better for it to be a rat than a mouse.\"","pt":"Digo à mamã; só que digo que foi uma ratazana, porque uma ratazana é maior do que um rato e come mais, e, como eu comi quase tudo, é melhor ser uma ratazana do que um rato.","es":"Se lo diré a mamá; solo que diré que era una rata, porque una rata es más grande que un ratón y come más, y, como me lo he comido casi todo, es mejor que sea una rata que un ratón»."}]},{"poem":false,"s":[{"fr":"Sophie, enchantée de son esprit, ferme la boîte, la remet à sa place et descend du fauteuil.","en":"Sophie, delighted with her own cleverness, shuts the box, puts it back in its place and climbs down from the armchair.","pt":"A Sophie, encantada com a sua esperteza, fecha a caixa, volta a pô-la no lugar e desce da poltrona.","es":"Sophie, encantada de lo lista que es, cierra la caja, la vuelve a poner en su sitio y se baja del sillón."},{"fr":"Elle retourne au jardin en courant ; à peine avait-elle eu le temps de prendre sa pelle, que Paul revint.","en":"She runs back to the garden; she has hardly had time to pick up her spade when Paul comes back.","pt":"Volta a correr para o jardim; mal teve tempo de pegar na pá, o Paul chegou.","es":"Vuelve corriendo al jardín; apenas le había dado tiempo a coger su pala cuando volvió Paul."}]},{"poem":false,"s":[{"fr":"J’ai été bien longtemps, n’est-ce pas ? c’est que je ne trouvais pas mes souliers ; on les avait emportés pour les cirer, et j’ai cherché partout avant de les demander à Baptiste.","en":"I was a long time, wasn't I? I couldn't find my shoes; they'd been taken away to be polished, and I looked everywhere before asking Baptiste for them.","pt":"Demorei muito, não foi? É que não encontrava os sapatos; tinham-nos levado para engraxar, e procurei por todo o lado antes de os pedir ao Baptiste.","es":"He tardado mucho, ¿verdad? Es que no encontraba los zapatos; se los habían llevado para limpiarlos, y lo he buscado por todas partes antes de pedírselos a Baptiste."},{"fr":"Qu’as-tu fait pendant que je n’y étais pas ?","en":"What did you do while I wasn't here?","pt":"Que fizeste enquanto eu não estava?","es":"¿Qué has hecho mientras yo no estaba?"}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Rien du tout, je t’attendais ; je jouais avec l’eau.","en":"Nothing at all; I was waiting for you; I was playing with the water.","pt":"Nada, estava à tua espera; brincava com a água.","es":"Nada de nada, te esperaba; jugaba con el agua."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Mais tu as laissé le bassin se vider ; il n’y a plus rien dedans.","en":"But you've let the pond empty; there's nothing left in it.","pt":"Mas deixaste o lago esvaziar-se; já não tem nada.","es":"Pero has dejado que se vacíe el estanque; ya no queda nada dentro."},{"fr":"Donne-moi ta pelle, que je batte un peu le fond pour le rendre plus solide ; va pendant ce temps puiser de l’eau dans le baquet.","en":"Give me your spade so I can pat the bottom down a bit to make it firmer; meanwhile, go and get some water from the tub.","pt":"Dá-me a tua pá, para eu bater um bocado o fundo e o tornar mais firme; entretanto vai buscar água à selha.","es":"Dame tu pala, que voy a apisonar un poco el fondo para que esté más firme; mientras tanto, ve a sacar agua del barreño."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Sophie alla chercher de l’eau pendant que Paul travaillait au bassin.","en":"Sophie went to get water while Paul worked on the pond.","pt":"A Sophie foi buscar água enquanto o Paul trabalhava no lago.","es":"Sophie fue a buscar agua mientras Paul trabajaba en el estanque."},{"fr":"Quand elle revint, Paul lui rendit la pelle et dit :","en":"When she came back, Paul gave her back the spade and said:","pt":"Quando voltou, o Paul devolveu-lhe a pá e disse:","es":"Cuando volvió, Paul le devolvió la pala y le dijo:"}]},{"poem":false,"s":[{"fr":"« Ta pelle est toute poissée ; elle colle aux doigts ; qu’est-ce que tu as mis dessus ?","en":"\"Your spade is all sticky; it sticks to your fingers; what have you put on it?\"","pt":"— A tua pá está toda peganhenta; cola-se aos dedos; o que lhe puseste?","es":"«Tu pala está toda pringosa; se pega a los dedos; ¿qué le has echado?"}]},{"poem":false,"s":[{"fr":"— Rien, répondit Sophie ; rien.","en":"\"Nothing,\" answered Sophie, \"nothing.","pt":"— Nada — respondeu a Sophie —, nada.","es":"—Nada», respondió Sophie; «nada."},{"fr":"Je ne sais pas pourquoi elle colle. »","en":"I don't know why it's sticky.\"","pt":"Não sei porque é que está a colar.","es":"No sé por qué se pega»."}]},{"poem":false,"s":[{"fr":"Et Sophie plongea vivement ses mains dans l’arrosoir plein d’eau, parce qu’elle venait de s’apercevoir qu’elles étaient poissées.","en":"And Sophie quickly plunged her hands into the watering can full of water, because she had just noticed that they were sticky.","pt":"E a Sophie meteu depressa as mãos no regador cheio de água, porque acabava de reparar que estavam peganhentas.","es":"Y Sophie metió deprisa las manos en la regadera llena de agua, porque acababa de darse cuenta de que las tenía pringosas."}]},{"poem":false,"s":[{"fr":"« Pourquoi mets-tu tes mains dans l’arrosoir ? demanda Paul.","en":"\"Why are you putting your hands in the watering can?\" asked Paul.","pt":"— Porque é que metes as mãos no regador? — perguntou o Paul.","es":"«¿Por qué metes las manos en la regadera?», preguntó Paul."}]},{"poem":false,"s":[{"fr":"Pour voir si elle est froide.","en":"To see if it's cold.","pt":"Para ver se está fria.","es":"Para ver si está fría."}],"who":{"fr":"Sophie, embarrassée","en":"Sophie, embarrassed","pt":"Sophie, embaraçada","es":"Sophie, apurada"}},{"poem":false,"s":[{"fr":"Quel drôle d’air tu as depuis que je suis revenu !","en":"What a funny look you've had since I came back!","pt":"Que ar tão esquisito tens desde que voltei!","es":"¡Qué cara tan rara tienes desde que he vuelto!"},{"fr":"On dirait que tu as fait quelque chose de mal.","en":"Anyone would think you'd done something wrong.","pt":"Parece que fizeste alguma coisa de mal.","es":"Parece que hayas hecho algo malo."}],"who":{"fr":"Paul, riant","en":"Paul, laughing","pt":"Paul, a rir","es":"Paul, riendo"}},{"poem":false,"s":[{"fr":"Quel mal veux-tu que j’aie fait !","en":"What wrong could I have done!","pt":"Que mal queres tu que eu tenha feito!","es":"¡Qué voy a haber hecho de malo!"},{"fr":"Tu n’as qu’à regarder ; tu ne trouveras rien de mal.","en":"You only have to look; you won't find anything wrong.","pt":"Basta olhares; não vais encontrar mal nenhum.","es":"No tienes más que mirar; no encontrarás nada malo."},{"fr":"Je ne sais pas pourquoi tu dis que j’ai fait quelque chose de mal : tu as toujours des idées ridicules.","en":"I don't know why you say I've done something wrong: you always have ridiculous ideas.","pt":"Não sei porque dizes que fiz alguma coisa de mal: tens sempre ideias ridículas.","es":"No sé por qué dices que he hecho algo malo: siempre tienes ideas ridículas."}],"who":{"fr":"Sophie, troublée","en":"Sophie, flustered","pt":"Sophie, perturbada","es":"Sophie, turbada"}},{"poem":false,"s":[{"fr":"Comme tu te fâches !","en":"How cross you're getting!","pt":"Como te zangas!","es":"¡Cómo te enfadas!"},{"fr":"C’est une plaisanterie que j’ai faite.","en":"I was only joking.","pt":"Foi uma brincadeira.","es":"Era una broma."},{"fr":"Je t’assure que je ne crois à aucune mauvaise action de ta part, et tu n’as pas besoin de me regarder d’un air si farouche. »","en":"I promise I don't believe you've done anything bad, and you don't need to look at me so fiercely.\"","pt":"Garanto-te que não acredito que tenhas feito nada de mal, e não precisas de olhar para mim com esse ar tão feroz.","es":"Te aseguro que no creo que hayas hecho nada malo, y no hace falta que me mires con esa cara tan hosca»."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Sophie leva les épaules, reprit son arrosoir et le versa dans le bassin, qui se vida sur le sable.","en":"Sophie shrugged her shoulders, picked up her watering can again and poured it into the pond, which drained away into the sand.","pt":"A Sophie encolheu os ombros, voltou a pegar no regador e despejou-o no lago, que se esvaziou na areia.","es":"Sophie se encogió de hombros, volvió a coger su regadera y la vació en el estanque, que se vació sobre la arena."},{"fr":"Les enfants jouèrent ainsi jusqu’à huit heures ; les bonnes vinrent les chercher et les emmenèrent.","en":"The children played like that until eight o'clock; the nannies came to fetch them and took them away.","pt":"As crianças brincaram assim até às oito horas; as amas vieram buscá-las e levaram-nas.","es":"Los niños jugaron así hasta las ocho; las niñeras vinieron a buscarlos y se los llevaron."},{"fr":"C’était l’heure du coucher.","en":"It was bedtime.","pt":"Era a hora de deitar.","es":"Era la hora de acostarse."}]},{"poem":false,"s":[{"fr":"Sophie eut une nuit un peu agitée ; elle rêva qu’elle était près d’un jardin dont elle était séparée par une barrière ; ce jardin était rempli de fleurs et de fruits qui semblaient délicieux.","en":"Sophie had a rather restless night; she dreamed she was near a garden that was separated from her by a fence; the garden was full of flowers and fruit that looked delicious.","pt":"A Sophie teve uma noite um pouco agitada; sonhou que estava ao pé de um jardim de que estava separada por uma vedação; esse jardim estava cheio de flores e de frutos que pareciam deliciosos.","es":"Sophie pasó una noche algo agitada; soñó que estaba junto a un jardín del que la separaba una barrera; aquel jardín estaba lleno de flores y de frutas que parecían deliciosas."},{"fr":"Elle cherchait à y entrer ; son bon ange la tirait en arrière et lui disait d’une voix triste :","en":"She tried to get in; her guardian angel pulled her back and said to her in a sad voice:","pt":"Ela procurava entrar; o seu anjo da guarda puxava-a para trás e dizia-lhe com voz triste:","es":"Intentaba entrar; su ángel de la guarda tiraba de ella hacia atrás y le decía con voz triste:"},{"fr":"« N’entre pas, Sophie ; ne goûte pas à ces fruits qui te semblent si bons, et qui sont amers et empoisonnés ;","en":"\"Don't go in, Sophie; don't taste those fruits that look so good to you, which are bitter and poisonous;","pt":"— Não entres, Sophie; não proves esses frutos que te parecem tão bons, e que são amargos e envenenados;","es":"«No entres, Sophie; no pruebes esas frutas que te parecen tan buenas y que son amargas y venenosas;"},{"fr":"ne sens pas ces fleurs qui paraissent si belles et qui répandent une odeur infecte et empoisonnée.","en":"don't smell those flowers that look so beautiful and give off a foul, poisonous smell.","pt":"não cheires essas flores que parecem tão bonitas e que espalham um cheiro horrível e venenoso.","es":"no huelas esas flores que parecen tan bonitas y que despiden un olor apestoso y venenoso."},{"fr":"Ce jardin est le jardin du mal.","en":"This garden is the garden of evil.","pt":"Este jardim é o jardim do mal.","es":"Este jardín es el jardín del mal."},{"fr":"Laisse-moi te mener dans le jardin du bien.","en":"Let me take you to the garden of good.\"","pt":"Deixa-me levar-te ao jardim do bem.","es":"Déjame llevarte al jardín del bien."},{"fr":"— Mais, dit Sophie, le chemin pour y aller est raboteux, plein de pierres, tandis que l’autre est couvert d’un sable fin, doux aux pieds.","en":"\"But,\" said Sophie, \"the path there is rough and full of stones, while the other one is covered with fine sand, soft under your feet.\"","pt":"— Mas — disse a Sophie — o caminho para lá é áspero, cheio de pedras, enquanto o outro está coberto de areia fina, macia para os pés.","es":"—Pero», dijo Sophie, «el camino para ir allí es áspero y está lleno de piedras, mientras que el otro está cubierto de una arena fina y suave para los pies."},{"fr":"— Oui, dit l’ange, mais le chemin raboteux te mènera dans un jardin de délices.","en":"\"Yes,\" said the angel, \"but the rough path will lead you to a garden of delights.","pt":"— Sim — disse o anjo —, mas o caminho áspero vai levar-te a um jardim de delícias.","es":"—Sí», dijo el ángel, «pero el camino áspero te llevará a un jardín de delicias."},{"fr":"L’autre chemin te mènera dans un lieu de souffrance, de tristesse ;","en":"The other path will lead you to a place of suffering and sadness;","pt":"O outro caminho vai levar-te a um lugar de sofrimento e de tristeza;","es":"El otro camino te llevará a un lugar de sufrimiento y de tristeza;"},{"fr":"tout y est mauvais ; les êtres qui l’habitent sont méchants et cruels ;","en":"everything there is bad; the creatures who live there are wicked and cruel;","pt":"tudo lá é mau; os seres que lá vivem são maus e cruéis;","es":"allí todo es malo; los seres que viven en él son malos y crueles;"},{"fr":"au lieu de te consoler, ils riront de tes souffrances, ils les augmenteront en te tourmentant eux-mêmes. »","en":"instead of comforting you, they'll laugh at your suffering and make it worse by tormenting you themselves.\"","pt":"em vez de te consolarem, vão rir-se dos teus sofrimentos e aumentá-los, atormentando-te eles próprios.","es":"en lugar de consolarte, se reirán de tus sufrimientos y los aumentarán atormentándote ellos mismos»."},{"fr":"Sophie hésita ; elle regardait le beau jardin rempli de fleurs, de fruits, les allées sablées et ombragées ;","en":"Sophie hesitated; she looked at the beautiful garden full of flowers and fruit, with its sandy, shady paths;","pt":"A Sophie hesitou; olhava para o belo jardim cheio de flores, de frutos, de áleas de areia e de sombra;","es":"Sophie dudó; miraba el hermoso jardín lleno de flores y frutas, los paseos de arena y a la sombra;"},{"fr":"puis, jetant un coup d’œil sur le chemin raboteux et aride qui semblait n’avoir pas de fin, elle se retourna vers la barrière, qui s’ouvrit devant elle, et, s’arrachant des mains de son bon ange, elle entra dans le jardin.","en":"then, glancing at the rough, barren path that seemed to have no end, she turned back to the fence, which opened in front of her, and, tearing herself from her guardian angel's hands, she went into the garden.","pt":"depois, deitando uma olhadela ao caminho áspero e árido que parecia não ter fim, virou-se para a vedação, que se abriu à sua frente, e, arrancando-se das mãos do seu anjo da guarda, entrou no jardim.","es":"luego, echando un vistazo al camino áspero y árido que parecía no tener fin, se volvió hacia la barrera, que se abrió ante ella, y, soltándose de las manos de su ángel de la guarda, entró en el jardín."},{"fr":"L’ange lui cria : « Reviens, reviens, Sophie, je t’attendrai à la barrière ; je t’y attendrai jusqu’à ta mort, et, si jamais tu reviens à moi, je te mènerai au jardin de délices par le chemin raboteux, qui s’adoucira et s’embellira à mesure que tu y avanceras. »","en":"The angel called out to her: \"Come back, come back, Sophie; I'll wait for you at the fence; I'll wait for you there until you die, and if you ever come back to me, I'll take you to the garden of delights by the rough path, which will grow smoother and lovelier the further you go along it.\"","pt":"O anjo gritou-lhe: — Volta, volta, Sophie, vou esperar por ti na vedação; vou esperar por ti até à tua morte e, se alguma vez voltares para mim, levo-te ao jardim de delícias pelo caminho áspero, que se tornará mais suave e mais bonito à medida que fores avançando.","es":"El ángel le gritó: «¡Vuelve, vuelve, Sophie! Te esperaré en la barrera; te esperaré allí hasta tu muerte, y, si alguna vez vuelves a mí, te llevaré al jardín de delicias por el camino áspero, que se irá suavizando y embelleciendo a medida que avances por él»."},{"fr":"Sophie n’écouta pas la voix de son bon ange : de jolis enfants lui faisaient signe d’avancer, elle courut à eux, ils l’entourèrent en riant, et se mirent les uns à la pincer, les autres à la tirailler, à lui jeter du sable dans les yeux.","en":"Sophie didn't listen to her guardian angel's voice: some pretty children were beckoning her on; she ran to them; they surrounded her, laughing, and some began to pinch her, others to pull her about and throw sand in her eyes.","pt":"A Sophie não ouviu a voz do seu anjo da guarda: umas crianças bonitas faziam-lhe sinal para avançar; ela correu para elas, rodearam-na a rir, e puseram-se umas a beliscá-la, outras a puxá-la, a atirar-lhe areia para os olhos.","es":"Sophie no escuchó la voz de su ángel de la guarda: unos niños muy bonitos le hacían señas para que se acercara; corrió hacia ellos, la rodearon riendo, y unos se pusieron a pellizcarla, otros a darle tirones y a echarle arena en los ojos."}]},{"poem":false,"s":[{"fr":"Sophie se débarrassa d’eux avec peine, et, s’éloignant, elle cueillit une fleur d’une apparence charmante ; elle la sentit et la rejeta loin d’elle : l’odeur en était affreuse.","en":"Sophie got away from them with difficulty and, walking off, picked a charming-looking flower; she smelled it and threw it far away: its smell was dreadful.","pt":"A Sophie livrou-se delas a custo e, afastando-se, colheu uma flor de aspeto encantador; cheirou-a e atirou-a para longe: o cheiro era horrível.","es":"Sophie se libró de ellos a duras penas y, alejándose, cogió una flor de aspecto precioso; la olió y la tiró lejos: tenía un olor espantoso."},{"fr":"Elle continua à avancer, et, voyant les arbres chargés des plus beaux fruits, elle en prit un et y goûta ; mais elle le jeta avec plus d’horreur encore que la fleur : le goût en était amer et détestable.","en":"She walked on and, seeing trees loaded with the most beautiful fruit, she picked one and tasted it; but she threw it away with even more horror than the flower: it tasted bitter and disgusting.","pt":"Continuou a avançar e, vendo as árvores carregadas dos frutos mais bonitos, apanhou um e provou-o; mas deitou-o fora com ainda mais horror do que a flor: o sabor era amargo e detestável.","es":"Siguió avanzando y, al ver los árboles cargados de las frutas más hermosas, cogió una y la probó; pero la tiró con más horror todavía que la flor: tenía un sabor amargo y asqueroso."},{"fr":"Sophie, un peu attristée, continua sa promenade, mais partout elle fut trompée comme pour les fleurs et les fruits.","en":"Sophie, a little saddened, went on with her walk, but everywhere she was deceived, just as with the flowers and the fruit.","pt":"A Sophie, um pouco entristecida, continuou o passeio, mas por todo o lado foi enganada como com as flores e os frutos.","es":"Sophie, un poco entristecida, siguió su paseo, pero en todas partes la engañaron como con las flores y las frutas."},{"fr":"Quand elle fut restée quelque temps dans ce jardin où tout était mauvais, elle pensa à son bon ange, et, malgré les promesses et les cris des méchants, elle courut à la barrière et aperçut son bon ange, qui lui tendait les bras.","en":"When she had stayed for some time in this garden where everything was bad, she thought of her guardian angel and, in spite of the wicked children's promises and shouts, she ran to the fence and saw her guardian angel holding out his arms to her.","pt":"Depois de estar algum tempo naquele jardim onde tudo era mau, pensou no seu anjo da guarda e, apesar das promessas e dos gritos dos maus, correu para a vedação e viu o seu anjo da guarda, que lhe estendia os braços.","es":"Cuando hubo estado un rato en aquel jardín donde todo era malo, pensó en su ángel de la guarda y, a pesar de las promesas y los gritos de los malos, corrió a la barrera y vio a su ángel de la guarda, que le tendía los brazos."},{"fr":"Repoussant les méchants enfants, elle se jeta dans les bras de l’ange, qui l’entraîna dans le chemin raboteux.","en":"Pushing away the wicked children, she threw herself into the angel's arms, and he led her onto the rough path.","pt":"Afastando as crianças más, atirou-se para os braços do anjo, que a levou pelo caminho áspero.","es":"Apartando a los niños malos, se echó en los brazos del ángel, que se la llevó por el camino áspero."},{"fr":"Les premiers pas lui parurent difficiles, mais plus elle avançait et plus le chemin devenait doux, plus le pays lui semblait frais et agréable.","en":"The first steps seemed hard to her, but the further she went, the smoother the path became and the fresher and more pleasant the country looked.","pt":"Os primeiros passos pareceram-lhe difíceis, mas quanto mais avançava, mais suave ficava o caminho e mais fresca e agradável lhe parecia a paisagem.","es":"Los primeros pasos le parecieron difíciles, pero cuanto más avanzaba, más suave se volvía el camino y más fresco y agradable le parecía el paisaje."},{"fr":"Elle allait entrer dans le jardin du bien, lorsqu’elle s’éveilla agitée et baignée de sueur.","en":"She was about to enter the garden of good when she woke up, agitated and bathed in sweat.","pt":"Ia entrar no jardim do bem quando acordou agitada e alagada em suor.","es":"Iba a entrar en el jardín del bien cuando se despertó agitada y empapada en sudor."},{"fr":"Elle pensa longtemps à ce rêve.","en":"She thought about this dream for a long time.","pt":"Pensou muito tempo neste sonho.","es":"Pensó mucho rato en aquel sueño."},{"fr":"« Il faudra, dit-elle, que je demande à maman de me l’expliquer » ; et elle se rendormit jusqu’au lendemain.","en":"\"I'll have to ask Mama to explain it to me,\" she said, and she went back to sleep until the morning.","pt":"— Tenho de pedir à mamã que mo explique — disse ela; e voltou a adormecer até de manhã.","es":"«Tendré que pedirle a mamá que me lo explique», dijo; y se volvió a dormir hasta el día siguiente."}]},{"poem":false,"s":[{"fr":"Quand elle alla chez sa maman, elle lui trouva le visage un peu sévère ; mais le rêve lui avait fait oublier les fruits confits, et elle se mit tout de suite à le raconter.","en":"When she went to her mother's room, she found her looking rather stern; but the dream had made her forget the candied fruit, and she began telling it straight away.","pt":"Quando foi ter com a mãe, achou-lhe a cara um pouco severa; mas o sonho tinha-a feito esquecer as frutas cristalizadas, e pôs-se logo a contá-lo.","es":"Cuando fue al cuarto de su mamá, le encontró la cara un poco severa; pero el sueño le había hecho olvidar la fruta confitada, y se puso enseguida a contárselo."}]},{"poem":false,"s":[{"fr":"Sais-tu ce qu’il peut signifier, Sophie !","en":"Do you know what it might mean, Sophie?","pt":"Sabes o que pode querer dizer, Sophie?","es":"¿Sabes lo que puede significar, Sophie?"},{"fr":"C’est que le bon Dieu, qui voit que tu n’es pas sage, te prévient par le moyen de ce rêve que, si tu continues à faire tout ce qui est mal et qui te semble agréable, tu auras des chagrins au lieu d’avoir des plaisirs.","en":"It means that God, who sees that you aren't good, is warning you through this dream that if you go on doing everything that's wrong and seems pleasant to you, you'll have sorrows instead of pleasures.","pt":"É que Deus, que vê que não te portas bem, te avisa por meio deste sonho que, se continuares a fazer tudo o que é mal e te parece agradável, vais ter desgostos em vez de prazeres.","es":"Que Dios, que ve que no te portas bien, te avisa por medio de este sueño de que, si sigues haciendo todo lo que está mal y te parece agradable, tendrás penas en lugar de alegrías."},{"fr":"Ce jardin trompeur, c’est l’enfer ; le jardin du bien, c’est le paradis ;","en":"That deceitful garden is hell; the garden of good is paradise;","pt":"Esse jardim enganador é o inferno; o jardim do bem é o paraíso;","es":"Ese jardín engañoso es el infierno; el jardín del bien es el paraíso;"},{"fr":"on y arrive par un chemin raboteux, c’est-à-dire en se privant de choses agréables, mais qui sont défendues ;","en":"you get there by a rough path, that is, by going without pleasant things that are forbidden;","pt":"chega-se lá por um caminho áspero, ou seja, privando-nos de coisas agradáveis mas que são proibidas;","es":"se llega por un camino áspero, es decir, privándose de cosas agradables, pero que están prohibidas;"},{"fr":"le chemin devient plus doux à mesure qu’on marche, c’est-à-dire qu’à force d’être obéissant, doux, bon, on s’y habitue tellement que cela ne coûte plus d’obéir et d’être bon, et qu’on ne souffre plus de ne pas se laisser aller à toutes ses volontés.","en":"the path gets smoother as you walk, that is, by being obedient, gentle and good, you get so used to it that it no longer costs you anything to obey and be good, and you no longer suffer from not giving in to all your wishes.","pt":"o caminho fica mais suave à medida que se anda, ou seja, à força de ser obediente, meigo e bom, habituamo-nos tanto que já não custa obedecer e ser bom, e já não sofremos por não fazer todas as nossas vontades.","es":"el camino se vuelve más suave a medida que se avanza, es decir, que a fuerza de ser obediente, dulce y bueno, uno se acostumbra tanto que ya no cuesta obedecer y ser bueno, y ya no sufre por no hacer siempre su voluntad."}],"who":{"fr":"La maman","en":"Mother","pt":"a mãe","es":"Mamá"}},{"poem":false,"s":[{"fr":"Sophie s’agita sur sa chaise ; elle rougissait, regardait sa maman ; elle voulait parler ; mais elle ne pouvait s’y décider.","en":"Sophie fidgeted on her chair; she was blushing and looking at her mother; she wanted to speak, but she couldn't make up her mind.","pt":"A Sophie mexia-se na cadeira; corava, olhava para a mãe; queria falar, mas não se conseguia decidir.","es":"Sophie se revolvió en su silla; se sonrojaba y miraba a su mamá; quería hablar, pero no se decidía."},{"fr":"Enfin Mme de Réan, qui voyait son agitation, vint à son aide en lui disant :","en":"At last Madame de Réan, who could see how agitated she was, came to her help by saying:","pt":"Por fim, a senhora de Réan, que via a sua agitação, veio em sua ajuda, dizendo-lhe:","es":"Por fin, la señora de Réan, que veía su agitación, vino en su ayuda diciéndole:"}]},{"poem":false,"s":[{"fr":"« Tu as quelque chose à avouer, Sophie ; tu n’oses pas le faire, parce que cela coûte toujours d’avouer une faute.","en":"\"You have something to confess, Sophie; you don't dare, because it's always hard to own up to a fault.","pt":"— Tens alguma coisa para confessar, Sophie; não te atreves, porque custa sempre confessar uma falta.","es":"«Tienes algo que confesar, Sophie; no te atreves a hacerlo, porque siempre cuesta confesar una falta."},{"fr":"C’est précisément le chemin raboteux dans lequel t’appelle ton bon ange et qui te fait peur.","en":"That's exactly the rough path your guardian angel is calling you to, and it frightens you.","pt":"É precisamente o caminho áspero para onde te chama o teu anjo da guarda, e que te mete medo.","es":"Ese es precisamente el camino áspero al que te llama tu ángel de la guarda y que te da miedo."},{"fr":"Voyons, Sophie, écoute ton bon ange, et saute hardiment dans les pierres du chemin qu’il t’indique. »","en":"Come, Sophie, listen to your guardian angel and step boldly onto the stones of the path he's showing you.\"","pt":"Vá, Sophie, ouve o teu anjo da guarda e salta com coragem para as pedras do caminho que ele te mostra.","es":"Vamos, Sophie, escucha a tu ángel de la guarda y salta con valor a las piedras del camino que te señala»."}]},{"poem":false,"s":[{"fr":"Sophie rougit plus encore, cacha sa figure dans ses mains et, d’une voix tremblante, avoua à sa maman qu’elle avait mangé la veille presque toute la boîte de fruits confits.","en":"Sophie went even redder, hid her face in her hands and, in a trembling voice, confessed to her mother that the day before she had eaten almost the whole box of candied fruit.","pt":"A Sophie corou ainda mais, escondeu a cara nas mãos e, com voz trémula, confessou à mãe que na véspera tinha comido quase a caixa toda de frutas cristalizadas.","es":"Sophie se sonrojó todavía más, se tapó la cara con las manos y, con voz temblorosa, le confesó a su mamá que el día anterior se había comido casi toda la caja de fruta confitada."}]},{"poem":false,"s":[{"fr":"Et comment espérais-tu me le cacher ?","en":"And how did you hope to hide it from me?","pt":"E como é que esperavas esconder-mo?","es":"¿Y cómo esperabas ocultármelo?"}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Je voulais vous dire, maman, que c’étaient les rats qui l’avaient mangée.","en":"I was going to tell you, Mama, that the rats had eaten it.","pt":"Queria dizer-lhe, mamã, que tinham sido as ratazanas a comê-la.","es":"Quería decirle, mamá, que se la habían comido las ratas."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Et je ne l’aurais jamais cru, comme tu le penses bien, puisque les rats ne pouvaient lever le couvercle de la boîte et le refermer ensuite ;","en":"And I would never have believed it, as you can imagine, since rats couldn't lift the lid of the box and then close it again;","pt":"E eu nunca teria acreditado, como bem calculas, porque as ratazanas não podiam levantar a tampa da caixa e voltar a fechá-la;","es":"Y yo nunca lo habría creído, como te puedes imaginar, porque las ratas no podían levantar la tapa de la caja y volver a cerrarla después;"},{"fr":"les rats auraient commencé par dévorer, déchirer la boîte pour arriver aux fruits confits.","en":"rats would have started by gnawing and tearing the box to get at the candied fruit.","pt":"as ratazanas teriam começado por roer e rasgar a caixa para chegar às frutas.","es":"las ratas habrían empezado por roer y destrozar la caja para llegar a la fruta confitada."},{"fr":"De plus, les rats n’avaient pas besoin d’approcher un fauteuil pour atteindre l’étagère.","en":"What's more, rats wouldn't have needed to pull up an armchair to reach the shelf.","pt":"Além disso, as ratazanas não precisavam de chegar uma poltrona para alcançar a prateleira.","es":"Además, las ratas no necesitaban acercar un sillón para alcanzar la estantería."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Comment !","en":"What!","pt":"Como!","es":"¡Cómo!"},{"fr":"Vous avez vu que j’avais tiré le fauteuil ?","en":"You saw I'd pulled up the armchair?","pt":"Viu que eu tinha puxado a poltrona?","es":"¿Vio usted que había acercado el sillón?"}],"who":{"fr":"Sophie, surprise","en":"Sophie, surprised","pt":"Sophie, surpreendida","es":"Sophie, sorprendida"}},{"poem":false,"s":[{"fr":"Comme tu avais oublié de l’ôter, c’est la première chose que j’ai vue hier en rentrant chez moi.","en":"Since you forgot to move it back, it was the first thing I saw when I came back to my room yesterday.","pt":"Como te esqueceste de a tirar, foi a primeira coisa que vi ontem ao voltar para o quarto.","es":"Como se te había olvidado quitarlo, fue lo primero que vi ayer al volver a mi cuarto."},{"fr":"J’ai compris que c’était toi, surtout après avoir regardé la boîte et l’avoir trouvée presque vide.","en":"I realised it was you, especially after looking at the box and finding it almost empty.","pt":"Percebi que tinhas sido tu, sobretudo depois de olhar para a caixa e a encontrar quase vazia.","es":"Comprendí que habías sido tú, sobre todo después de mirar la caja y encontrarla casi vacía."},{"fr":"Tu vois comme tu as bien fait de m’avouer ta faute ; tes mensonges n’auraient fait que l’augmenter et t’auraient fait punir plus sévèrement.","en":"You see how right you were to confess your fault; your lies would only have made it worse and got you punished more severely.","pt":"Vês como fizeste bem em confessar a tua falta; as tuas mentiras só a teriam agravado e far-te-iam ser castigada com mais severidade.","es":"Ya ves qué bien has hecho en confesarme tu falta; tus mentiras no habrían hecho más que agravarla y habrían hecho que te castigaran con más severidad."},{"fr":"Pour récompenser l’effort que tu fais en avouant tout, tu n’auras d’autre punition que de ne pas manger de fruits confits tant qu’ils dureront.","en":"To reward the effort you're making in owning up to everything, your only punishment will be not to eat any candied fruit as long as it lasts.","pt":"Para recompensar o esforço que fazes ao confessar tudo, o teu único castigo vai ser não comer frutas cristalizadas enquanto elas durarem.","es":"Para recompensar el esfuerzo que haces al confesarlo todo, no tendrás más castigo que no comer fruta confitada mientras dure."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Sophie baisa la main de sa maman, qui l’embrassa ; elle retourna ensuite dans sa chambre, où Paul l’attendait pour déjeuner.","en":"Sophie kissed her mother's hand, and her mother kissed her; then she went back to her room, where Paul was waiting for her for breakfast.","pt":"A Sophie beijou a mão da mãe, que lhe deu um beijo; depois voltou para o quarto, onde o Paul esperava por ela para o pequeno-almoço.","es":"Sophie le besó la mano a su mamá, que le dio un beso; luego volvió a su cuarto, donde Paul la esperaba para desayunar."}]},{"poem":false,"s":[{"fr":"Qu’as-tu donc, Sophie ?","en":"What's the matter, Sophie?","pt":"Que tens, Sophie?","es":"¿Qué te pasa, Sophie?"},{"fr":"Tu as les yeux rouges.","en":"Your eyes are red.","pt":"Tens os olhos vermelhos.","es":"Tienes los ojos rojos."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"C’est que j’ai pleuré.","en":"It's because I've been crying.","pt":"É que estive a chorar.","es":"Es que he llorado."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Pourquoi ?","en":"Why?","pt":"Porquê?","es":"¿Por qué?"},{"fr":"Est-ce que ma tante t’a grondée ?","en":"Did my aunt scold you?","pt":"A tia ralhou contigo?","es":"¿Te ha regañado mi tía?"}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Non, mais c’est que j’étais honteuse de lui avouer une mauvaise chose que j’ai faite hier.","en":"No, but I was ashamed to confess to her a bad thing I did yesterday.","pt":"Não, mas é que estava envergonhada de lhe confessar uma coisa má que fiz ontem.","es":"No, es que me daba vergüenza confesarle una cosa mala que hice ayer."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Quelle mauvaise chose ?","en":"What bad thing?","pt":"Que coisa má?","es":"¿Qué cosa mala?"},{"fr":"Je n’ai rien vu, moi.","en":"I didn't see anything.","pt":"Eu não vi nada.","es":"Yo no he visto nada."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Parce que je me suis cachée de toi.","en":"Because I hid from you.","pt":"Porque me escondi de ti.","es":"Porque me escondí de ti."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Et Sophie raconta à Paul comment elle avait mangé la boîte de fruits confits, après avoir voulu seulement les regarder et choisir les meilleurs pour le lendemain.","en":"And Sophie told Paul how she had eaten the box of candied fruit after only meaning to look at it and choose the best ones for the next day.","pt":"E a Sophie contou ao Paul como tinha comido a caixa de frutas cristalizadas, depois de só ter querido olhar para elas e escolher as melhores para o dia seguinte.","es":"Y Sophie le contó a Paul cómo se había comido la caja de fruta confitada, cuando solo había querido mirarla y elegir las mejores para el día siguiente."}]},{"poem":false,"s":[{"fr":"Paul loua beaucoup Sophie d’avoir tout avoué à sa maman.","en":"Paul praised Sophie warmly for confessing everything to her mother.","pt":"O Paul elogiou muito a Sophie por ter confessado tudo à mãe.","es":"Paul alabó mucho a Sophie por habérselo confesado todo a su mamá."}]},{"poem":false,"s":[{"fr":"« Comment as-tu eu ce courage ? » dit-il.","en":"\"How did you find the courage?\" he said.","pt":"— Como é que tiveste essa coragem? — disse ele.","es":"«¿Cómo has tenido ese valor?», dijo."}]},{"poem":false,"s":[{"fr":"Sophie lui raconta alors son rêve, et comment sa maman le lui avait expliqué.","en":"Then Sophie told him about her dream and how her mother had explained it to her.","pt":"A Sophie contou-lhe então o sonho, e como a mãe lho tinha explicado.","es":"Entonces Sophie le contó su sueño y cómo se lo había explicado su mamá."},{"fr":"Depuis ce jour Paul et Sophie parlèrent souvent de ce rêve, qui les aida à être obéissants et bons.","en":"From that day on, Paul and Sophie often talked about the dream, which helped them to be obedient and good.","pt":"Desde esse dia, o Paul e a Sophie falaram muitas vezes daquele sonho, que os ajudou a ser obedientes e bons.","es":"Desde aquel día, Paul y Sophie hablaron a menudo de aquel sueño, que los ayudó a ser obedientes y buenos."}]}]});
